/**
 * GetSibu content model.
 *
 * Three layers, each with one owner:
 *
 * 1. Source      — `content/source/pdf-pages.json`. Verbatim extraction of Getsibu.pdf.
 *                  Generated by `scripts/extract-pdf-source.ts`. Never hand-edited.
 * 2. Architecture — `content/architecture/*.ts`. Hand-curated decisions: sections, URL rules,
 *                  page types, clusters, navigation, claims register.
 * 3. Inventory   — `content/generated/inventory.json`. Source × architecture, generated by
 *                  `scripts/build-inventory.ts`. Every route, SEO field and link is resolved here.
 *
 * Authored page bodies (Prompt 2+) live in `content/pages/**` as `PageContent` and are merged
 * onto the inventory entry at render time. They never redefine slug, title or SEO identity.
 *
 * All architecture modules may only use `import type` from this file so that Node's
 * type stripping can execute the build scripts without a compiler.
 */

/* ------------------------------------------------------------------------------------------ */
/* Source layer                                                                                */
/* ------------------------------------------------------------------------------------------ */

export interface PdfGroup {
  /** e.g. "11-30" */
  range: string;
  start: number;
  end: number;
  /** Heading exactly as written in the PDF, or a descriptive label when the PDF has none. */
  label: string;
  /** False for pages 1-10, which appear before the first group heading. */
  headingInSource: boolean;
}

export interface SourcePage {
  /** The page number as written in the PDF (1-400). Stable identity for every page. */
  number: number;
  /** Title exactly as written in the PDF. */
  sourceTitle: string;
  /** Title with typographic normalisation only ("--" → "—"). */
  title: string;
  /** Body paragraph exactly as written, line breaks joined. */
  text: string;
  group: PdfGroup;
}

/* ------------------------------------------------------------------------------------------ */
/* Provenance                                                                                  */
/* ------------------------------------------------------------------------------------------ */

/**
 * Every authored fact must point at where it came from. `editorial` is only for connective,
 * claim-free copy (headings like "Related capabilities", transitions, instructions).
 */
export type SourceRef =
  | { kind: "pdf"; page: number }
  | { kind: "site"; url: string; retrieved: string }
  | { kind: "editorial"; note?: string };

