export type SearchIntent = "navigational" | "commercial" | "informational" | "transactional";

/**
 * Groups shown in global search results. They follow the PDF hierarchy: each is a category label (the
 * PDF group a page belongs to, as recorded in content/architecture/sections.ts), ordered by PDF page number,
 * so a result is labelled with the same group as its breadcrumb and hub.
 */
export type SearchGroup =
  | "Platform"
  | "Search & Discovery"
  | "AI"
  | "Collaboration"
  | "Versioning & Asset Management"
  | "Storage & Ingestion"
  | "Permissions & Multi-Tenancy"
  | "Analytics"
  | "Use Cases"
  | "Integrations"
  | "API & Developers"
  | "Migration"
  | "Architecture & Performance"
  | "Security & Compliance"
  | "Pricing & Plans"
  | "Business Value"
  | "Resources"
  | "FAQs"
  | "Get Started";

export interface SectionDef {
  id: SectionId;
  /** URL root, e.g. "/features". Home is "/". */
  basePath: string;
  label: string;
  /**
   * PDF page that *is* the section overview and therefore owns `basePath`.
   * When absent, `basePath` is a generated index page (see `IndexPageDef`).
   */
  rootPage?: number;
  categories: CategoryId[];
}

export interface CategoryDef {
  id: CategoryId;
  section: SectionId;
  label: string;
  /** Short label for navigation columns and breadcrumbs. */
  shortLabel: string;
  /** PDF group ranges whose pages default into this category. */
  pdfRanges: Array<[number, number]>;
  /** Hub URL for the category. Equals the section basePath for single-category sections. */
  hubPath: string;
  pageType: PageTypeId;
  searchGroup: SearchGroup;
  /** Visual direction for the category, see docs/architecture/08-visual-and-image-strategy.md */
  visual: VisualDirection;
}

export interface IndexPageDef {
  id: string;
  path: string;
  section: SectionId;
  category?: CategoryId;
  title: string;
  h1: string;
  /** Intro shown under the H1: verbatim PDF sentence(s), cited, or claim-free editorial copy. */
  lede: string;
  ledeSource: SourceRef[];
  /**
   * Meta description. Written from PDF terminology (cluster and page names) rather than copied
   * from a page paragraph, so it can never collide with a PDF page's own description.
   */
  description: string;
  /** Cluster ids rendered as sub-groups, in order. Pages not in any listed cluster fall into "More". */
  groupBy: string[];
  /** Canonical pages from other sections that belong on this index. */
  crossListings?: number[];
}

export interface TopicCluster {
  id: string;
  label: string;
  /** Pillar page other members point to for the shared topic. */
  primary: number;
  members: number[];
  /**
   * "high" means members' PDF paragraphs are near-identical. Content authors must write to the
   * angle recorded in `angles` so the pages do not duplicate each other.
   */
  overlapRisk: "low" | "medium" | "high";
  /** Per-page angle, derived from where the PDF places the page. */
  angles?: Record<number, string>;
}

export type VisualMedium =
  | "product-ui"
  | "diagram"
  | "photography"
  | "data-visual"
  | "code-concept"
  | "typographic";

export interface VisualDirection {
  medium: VisualMedium[];
  concept: string;
  avoid: string[];
}

export type ClaimStatus =
  /** Present in the PDF; not found on the official website. */
  | "pdf-stated"
  /** The PDF itself hedges the claim ("stated positioning", "stated direction"). */
  | "pdf-hedged"
  /** Stated on the official website, with no conflict found. */
  | "site-stated"
  /** Stated on the official website, but the site contradicts itself or the product's own code does. */
  | "conflicting"
  /** Confirmed in writing by GetSibu. The only status that unlocks high-risk claims. */
  | "client-confirmed";

export interface Claim {
  id: string;
  statement: string;
  status: ClaimStatus;
  /**
   * "high": numbers, limits, certifications, compliance, named third parties, prices, security
   * mechanisms — publishable only when `client-confirmed`.
   * "standard": descriptive capability claims — publishable when PDF- or site-stated.
   */
  risk: "high" | "standard";
  /** PDF pages that state the claim. Empty for claims that appear only on the official site. */
  pdfPages: number[];
  /** Exact wording on the official site, when present. */
  siteWording?: string[];
  conflicts?: string[];
  evidence?: SourceRef[];
  /** Case-insensitive, word-bounded phrases the validator uses to detect the claim in copy. */
  detect: string[];
  note?: string;
}

/* ------------------------------------------------------------------------------------------ */
/* Inventory layer (generated)                                                                 */
/* ------------------------------------------------------------------------------------------ */

export interface BreadcrumbItem {
  label: string;
  path: string;
}

export interface CtaRef {
  /** "global:<id>" resolves from `lib/site.ts`; "page:<n>" links to a PDF conversion page. */
  target: string;
  label: string;
  href: string;
}

export interface SeoData {
  /** <title>. Brand appended unless the title already contains "GetSibu". */
  title: string;
  h1: string;
  /** Drafted from the first source sentence(s); ≤ 160 chars. */
  description: string;
  canonicalPath: string;
  /** schema.org types emitted for the page. */
  schemaTypes: string[];
  robots: "index,follow" | "noindex,follow";
  sitemap: boolean;
}

export interface InventoryPage {
  /** PDF page number, also the stable id. */
  number: number;
  title: string;
  sourceTitle: string;
  sourceText: string;
  pdfGroup: PdfGroup;

  status: "canonical" | "merged";
  /** For merged pages: the canonical page number whose URL serves this topic. */
  mergedInto?: number;
  /** For canonical pages: PDF pages merged into this one, whose paragraphs are extra source material. */
  mergedSources: number[];

  section: SectionId;
  category: CategoryId;
  role: "home" | "section-root" | "leaf";
  slug: string;
  /** Canonical URL path (merged pages carry the canonical page's path). */
  path: string;
  /** Paths that 308-redirect to `path`. */
  aliases: string[];
  parentPath: string | null;
  breadcrumb: BreadcrumbItem[];

  pageType: PageTypeId;
  /** Section recipe variant chosen for layout rhythm; see content/architecture/page-types.ts. */
  recipe: string;

  primaryTopic: string;
  intent: SearchIntent;
  /** What the page must accomplish for the reader. */
  purpose: string;
  /** The first sentence of the source paragraph — the page's core statement. */
  keyStatement: string;

  clusters: string[];
  /** Ordered, de-duplicated related pages (canonical numbers only). */
  related: number[];
  /** Concepts named in the source paragraph that have their own page. */
  mentions: number[];
  relatedFeatures: number[];
  relatedResources: number[];
  relatedFaqs: number[];
  relatedUseCases: number[];
  /** Pages listed under this page (section roots only). */
  children: number[];
  /** The same pages grouped by topic cluster, in display order (section roots only). */
  childGroups: Array<{ clusterId: string | null; label: string; pages: number[] }>;
  previous: number | null;
  next: number | null;

  cta: {
    primary: CtaRef;
    contextual: CtaRef | null;
  };

  seo: SeoData;
  searchGroup: SearchGroup;
  visual: VisualDirection & { subject: string };

  /** Claim ids detected in the source paragraph. */
  claims: string[];
  /** True when any detected claim is not publishable yet (see `isPublishable` in claims.ts). */
  needsVerification: boolean;
  /**
   * For pages that need verification: the publishable page that frames them (hero lede, meta
   * description). See content/architecture/verified-context.ts. Null for publishable pages.
   */
  contextPage: number | null;
  /**
   * published — no unconfirmed claims.
   * framed    — needs verification, but its title is safe: published with verified context.
   * held      — its title itself states an unconfirmed claim: not published anywhere; the URL
   *             redirects temporarily to the context page (content/architecture/verified-context.ts).
   */
  publication: "published" | "framed" | "held";
  /** Overlap notes the content author must respect. */
  angle: string | null;
}

/**
 * One row of the route matrix (content/generated/route-matrix.json, docs/route-matrix.csv): every URL
 * the site answers, with how it must behave. scripts/verify-build.ts checks the built site against it.
 *
 *   LIVE       canonical, published, indexable, in the sitemap and search
 *   SAFE-LIVE  published from verified material only; indexability set deliberately (framed pages,
 *              company pages, site search)
 *   HELD       an inventory page whose title states an unconfirmed claim: no page, navigation, sitemap
 *              or search entry; its URL redirects temporarily to verified context
 *   REDIRECT   an alias that publishes nothing (merged PDF duplicates, /about-us)
 */
export interface RouteMatrixRow {
  path: string;
  class: "LIVE" | "SAFE-LIVE" | "HELD" | "REDIRECT";
  kind: "home" | "page" | "hub" | "company" | "utility" | "held-page" | "merged-alias" | "supporting-alias";
  pdfPage: number | null;
  title: string;
  status: 200 | 307 | 308;
  destination: string | null;
  indexable: boolean;
  sitemap: boolean;
  search: boolean;
  navigation: boolean;
  /** Unpublishable claims behind a SAFE-LIVE or HELD row. */
  claims: string[];
  note: string;
}

export interface InventoryIndexPage extends IndexPageDef {
  seo: SeoData;
  breadcrumb: BreadcrumbItem[];
  groups: Array<{ clusterId: string | null; label: string; pages: number[] }>;
}

export interface Inventory {
  generatedAt: string;
  source: { file: string; pages: number };
  pages: InventoryPage[];
  indexes: InventoryIndexPage[];
  /** Permanent for merged duplicates; temporary while a page is held. */
  redirects: Array<{ source: string; destination: string; permanent: boolean }>;
}

/* ------------------------------------------------------------------------------------------ */
/* Authored content (Prompt 2+)                                                                */
/* ------------------------------------------------------------------------------------------ */

export interface MediaRef {
  /** Asset id in the media registry — each id may be used on one page only unless `shared`. */
  assetId: string;
  alt: string;
  /** Required when the visual is a product capture: which screen, supplied by whom. */
  provenance: SourceRef;
  aspect?: "16:9" | "4:3" | "3:2" | "1:1" | "4:5" | "21:9";
}

/**
 * Data-driven SVG figures (components/diagrams). A diagram draws facts from its section's sources;
 * it is never a mock-up of the product interface.
 */
export type DiagramId =
  | "library-search"
  | "search-signals"
  | "ai-review"
  | "timeline-review"
  | "version-record"
  | "folder-access"
  | "library-activity"
  | "tenant-boundaries"
  | "api-flow"
  | "ingest-pipeline"
  | "architecture-stack"
  | "migration-map"
  | "connector-flow"
  | "control-map"
  | "media-library";

/**
 * A diagram plus the part of it this page is about. `focus` is a diagram-specific key (for example
 * "ocr" on search-signals, "edge" on architecture-stack) that lights that part up, so pages sharing
 * a figure still show their own place in the system. `label` names an external tool (connector-flow).
 */
export interface VisualRef {
  diagram: DiagramId;
  focus?: string;
  label?: string;
}

/** A link to another page, always by PDF number; label defaults to the page title. */
/** Plain text, or text with inline links: each link wraps a phrase of the text and points at a page by PDF number. */
export type RichText = string | Array<string | { text: string; page: number }>;

export interface PageLinkRef {
  page: number;
  label?: string;
}

/**
 * Hero and CTA actions: the global CTAs from navigation.ts, a page by PDF number, or an inventory
 * route such as a hub (validated against the inventory).
 */
export type ActionRef =
  | { kind: "global"; cta: "primary" | "secondary" }
  | ({ kind: "page" } & PageLinkRef)
  | { kind: "route"; path: string; label: string };

/** An item in a set that may point at a page; `current` marks the page being viewed. */
interface Linked {
  page?: number;
  current?: boolean;
}

/**
 * Semantic icon names authored content may use. The presentation layer maps each name to a glyph, so
 * content never depends on an icon library. Icons decorate; the text beside them carries the meaning.
 */
