interface SectionBase {
  /** Stable id used for anchors and analytics. */
  id: string;
  sources: SourceRef[];
  /** Short label above the heading. Must name something true (a category, a step), not decorate. */
  eyebrow?: string;
  /** One or two sentences under the heading. */
  intro?: string;
  /** Visual rhythm hint for spacing: dense sections get tighter padding. */
  density?: "dense" | "open";
  /** Colour surface for the section band. */
  surface?: "default" | "muted" | "inverse";
}

export type ContentSection =
  | (SectionBase & {
      kind: "hero";
      /** Omitted when the page's source paragraph states a claim that is not publishable yet. */
      lede?: string;
      /** When the lede is another page's statement (pages that need verification): that page. */
      context?: PageLinkRef;
      media?: MediaRef;
      diagram?: DiagramId;
      visual?: VisualRef;
      layout: "split" | "centered" | "statement";
      actions?: ActionRef[];
      /** Up to three short checked items under the actions (homepage). Visible claims: sourced, never numeric. */
      points?: string[];
    })
  | (SectionBase & { kind: "definition"; term: string; answer: RichText; detail?: RichText })
  /**
   * The topic explained: 2–4 paragraphs, the key concepts as chips, an optional "in practice" callout
   * and an at-a-glance card. Glance facts and tags are visible claims: sourced, never numeric or priced
   * unless the claim is confirmed.
   */
  | (SectionBase & {
      kind: "overview";
      heading: string;
      body: RichText[];
      keyPoints: { heading: string; items: string[] };
      highlight?: { heading: string; body: RichText; tags?: string[] };
      glance?: { heading: string; facts: Array<{ label: string; value: string; page?: number }>; actions?: ActionRef[] };
    })
  /** Two to five views of one topic (by team, by asset type, by stage). Every panel is in the HTML. */
  | (SectionBase & {
      kind: "tabs";
      heading: string;
      tabs: Array<{ label: string; heading: string; body: RichText[]; points?: string[]; icon?: TopicIcon; visual?: VisualRef; link?: PageLinkRef }>;
    })
  /** Expandable deep dives: a one-line summary always visible, the detail on demand. */
  | (SectionBase & {
      kind: "accordion";
      heading: string;
      items: Array<{ heading: string; summary: string; body: RichText[]; points?: string[]; icon?: TopicIcon; page?: number }>;
    })
  /** An illustrative, unnamed team working through the topic. Every GetSibu action in it is sourced. */
  | (SectionBase & {
      kind: "scenario";
      heading: string;
      team: string;
      situation: RichText;
      steps: Array<{ heading: string; body: RichText }>;
      outcome: RichText;
      link?: PageLinkRef;
    })
  | (SectionBase & {
      kind: "editorial";
      heading: string;
      /** Plain paragraphs, or a lead-in (usually a page title) followed by that page's statement. */
      body: Array<string | ({ lead: string; text: string } & Linked)>;
    })
  | (SectionBase & {
      kind: "split";
      heading: string;
      body: string[];
      media?: MediaRef;
      diagram?: DiagramId;
      visual?: VisualRef;
      mediaSide: "start" | "end";
      points?: string[];
      links?: PageLinkRef[];
    })
  | (SectionBase & {
      kind: "story";
      heading: string;
      visual: VisualRef;
      steps: Array<{ heading: string; body: string; media?: MediaRef; focus?: string } & Linked>;
    })
  | (SectionBase & { kind: "workflow"; heading: string; stages: Array<{ label: string; body: string } & Linked> })
  | (SectionBase & { kind: "process"; heading: string; steps: Array<{ heading: string; body: string; icon?: TopicIcon } & Linked> })
  | (SectionBase & { kind: "timeline"; heading: string; items: Array<{ label: string; body: string } & Linked> })
  | (SectionBase & {
      kind: "capabilities";
      heading: string;
      items: Array<{ heading: string; body: string; icon?: TopicIcon; points?: string[] } & Linked>;
    })
  | (SectionBase & {
      kind: "category-explorer";
      heading: string;
      categories: Array<{ category: CategoryId; summary: string; pages: number[]; diagram: DiagramId }>;
    })
  | (SectionBase & {
      kind: "comparison";
      heading: string;
      columns: [string, string];
      rows: Array<[string, string, string]>;
      /** Which column is GetSibu's, so it can be emphasised. */
      emphasis?: 0 | 1;
    })
  | (SectionBase & {
      kind: "before-after";
      heading: string;
      beforeLabel: string;
      afterLabel: string;
      before: string[];
      after: string[];
      link?: PageLinkRef;
    })
  | (SectionBase & { kind: "statement"; text: string; attribution?: never; link?: PageLinkRef })
  | (SectionBase & { kind: "media"; media?: MediaRef; visual?: VisualRef; caption?: string })
  | (SectionBase & {
      kind: "alternating";
      heading: string;
      rows: Array<{ heading: string; body: string; media?: MediaRef; visual?: VisualRef } & Linked>;
    })
  | (SectionBase & { kind: "layers"; heading: string; layers: Array<{ label: string; body: string } & Linked> })
  | (SectionBase & {
      kind: "matrix";
      heading: string;
      columns: string[];
      rows: Array<{ label: string; cells: string[] } & Linked>;
    })
  | (SectionBase & { kind: "plans"; heading: string; planPages: number[] })
  | (SectionBase & {
      kind: "checklist";
      heading: string;
      /** "chips" renders short labels as a compact grid of pills. */
      variant?: "list" | "chips";
      /** A label, or a page whose inventory title is shown (titles of pages that need verification stay out of copy). */
      items: Array<string | ({ label: string } & Linked) | ({ label?: undefined; page: number } & Linked)>;
    })
  | (SectionBase & { kind: "event-list"; heading: string; events: Array<{ name: string; body: string } & Linked> })
  | (SectionBase & { kind: "faq"; heading: string; items: Array<{ question: string; answer: RichText; page?: number }> })
  /** "compact" is a short strip of small link cards (at most six), not a directory. */
  | (SectionBase & { kind: "related"; heading: string; pages: number[]; variant?: "index" | "cards" | "compact" })
  | (SectionBase & { kind: "cta"; heading: string; body?: string; conversionPage?: number; actions?: ActionRef[] });

export type SectionKind = ContentSection["kind"];

export interface PageContent {
  /** PDF page number this content belongs to. */
  page: number;
  /** Must equal the inventory recipe unless `recipeOverride` explains why. */
  recipeOverride?: { recipe: string; reason: string };
  sections: ContentSection[];
  /** Optional refinement of the drafted meta description. Title/H1/slug are not overridable here. */
  metaDescription?: string;
  lastReviewed: string;
}

